"""Highest version in a list satisfying an npm-style range. See task.md."""

from __future__ import annotations

import re
from dataclasses import dataclass
from typing import Optional, Tuple, List


class RangeError(ValueError):
    """Raised for malformed range expressions and malformed versions."""


@dataclass(frozen=True)
class Version:
    """Represents a semver version."""
    major: int
    minor: int
    patch: int
    prerelease: Tuple[str, ...] = ()
    build: Tuple[str, ...] = ()

    @staticmethod
    def parse(version_str: str) -> Version:
        """Parse and validate a version string."""
        pattern = r'^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$'
        match = re.match(pattern, version_str)

        if not match:
            raise RangeError(f"Malformed version: {version_str}")

        major, minor, patch, prerelease_str, build_str = match.groups()
        major, minor, patch = int(major), int(minor), int(patch)

        prerelease = ()
        if prerelease_str:
            prerelease_parts = prerelease_str.split('.')
            for part in prerelease_parts:
                if not part or not re.match(r'^[0-9A-Za-z-]+$', part):
                    raise RangeError(f"Malformed version: {version_str}")
                if part.isdigit() and len(part) > 1 and part[0] == '0':
                    raise RangeError(f"Malformed version: {version_str}")
            prerelease = tuple(prerelease_parts)

        build = ()
        if build_str:
            build_parts = build_str.split('.')
            for part in build_parts:
                if not part or not re.match(r'^[0-9A-Za-z-]+$', part):
                    raise RangeError(f"Malformed version: {version_str}")
            build = tuple(build_parts)

        return Version(major, minor, patch, prerelease, build)

    def compare_prerelease(self, other: Version) -> int:
        """Compare prerelease versions. Returns -1, 0, or 1."""
        if not self.prerelease and not other.prerelease:
            return 0

        if self.prerelease and not other.prerelease:
            return -1
        if not self.prerelease and other.prerelease:
            return 1

        for a, b in zip(self.prerelease, other.prerelease):
            a_is_digit = a.isdigit()
            b_is_digit = b.isdigit()

            if a_is_digit and b_is_digit:
                if int(a) < int(b):
                    return -1
                elif int(a) > int(b):
                    return 1
            elif a_is_digit and not b_is_digit:
                return -1
            elif not a_is_digit and b_is_digit:
                return 1
            else:
                if a < b:
                    return -1
                elif a > b:
                    return 1

        if len(self.prerelease) < len(other.prerelease):
            return -1
        elif len(self.prerelease) > len(other.prerelease):
            return 1

        return 0

    def compare(self, other: Version) -> int:
        """Compare versions by precedence. Returns -1, 0, or 1."""
        if self.major != other.major:
            return -1 if self.major < other.major else 1
        if self.minor != other.minor:
            return -1 if self.minor < other.minor else 1
        if self.patch != other.patch:
            return -1 if self.patch < other.patch else 1

        return self.compare_prerelease(other)

    def __lt__(self, other: Version) -> bool:
        return self.compare(other) == -1

    def __le__(self, other: Version) -> bool:
        return self.compare(other) <= 0

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        return (self.major == other.major and
                self.minor == other.minor and
                self.patch == other.patch and
                self.prerelease == other.prerelease)

    def __gt__(self, other: Version) -> bool:
        return self.compare(other) == 1

    def __ge__(self, other: Version) -> bool:
        return self.compare(other) >= 0


def parse_partial_version(version_str: str) -> Tuple[Optional[int], Optional[int], Optional[int], Optional[Tuple[str, ...]], Optional[Tuple[str, ...]]]:
    """Parse a partial version with wildcards."""
    pattern = r'^(.*?)(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$'
    match = re.match(pattern, version_str)
    if not match:
        raise RangeError(f"Malformed partial version: {version_str}")

    main_part, prerelease_str, build_str = match.groups()
    parts = main_part.split('.')

    if len(parts) > 3:
        raise RangeError(f"Malformed partial version: {version_str}")

    major = None
    minor = None
    patch = None

    for i, part in enumerate(parts):
        if part in ('x', 'X', '*'):
            break
        elif re.match(r'^(0|[1-9]\d*)$', part):
            val = int(part)
            if i == 0:
                major = val
            elif i == 1:
                minor = val
            elif i == 2:
                patch = val
        else:
            raise RangeError(f"Malformed partial version: {version_str}")

    prerelease = None
    if prerelease_str:
        if major is None or minor is None or patch is None:
            raise RangeError(f"Malformed partial version: {version_str}")
        prerelease_parts = prerelease_str.split('.')
        for part in prerelease_parts:
            if not part or not re.match(r'^[0-9A-Za-z-]+$', part):
                raise RangeError(f"Malformed partial version: {version_str}")
            if part.isdigit() and len(part) > 1 and part[0] == '0':
                raise RangeError(f"Malformed partial version: {version_str}")
        prerelease = tuple(prerelease_parts)

    build = None
    if build_str:
        if major is None or minor is None or patch is None:
            raise RangeError(f"Malformed partial version: {version_str}")
        build_parts = build_str.split('.')
        for part in build_parts:
            if not part or not re.match(r'^[0-9A-Za-z-]+$', part):
                raise RangeError(f"Malformed partial version: {version_str}")
        build = tuple(build_parts)

    return major, minor, patch, prerelease, build


def desugar_bare(major: Optional[int], minor: Optional[int], patch: Optional[int]) -> List[Tuple[str, Version]]:
    """Desugar a bare/= comparator with partial version."""
    if major is None:
        return [('>=', Version(0, 0, 0))]

    if minor is None:
        return [('>=', Version(major, 0, 0)), ('<', Version(major + 1, 0, 0))]

    if patch is None:
        return [('>=', Version(major, minor, 0)), ('<', Version(major, minor + 1, 0))]

    return [('=', Version(major, minor, patch))]


def desugar_caret(major: Optional[int], minor: Optional[int], patch: Optional[int], prerelease: Optional[Tuple[str, ...]], build: Optional[Tuple[str, ...]]) -> List[Tuple[str, Version]]:
    """Desugar a caret comparator."""
    if major is None:
        raise RangeError("Caret requires at least a major component")

    lower = Version(major, minor or 0, patch or 0, prerelease or (), build or ())

    if major != 0:
        upper = Version(major + 1, 0, 0)
    elif minor is None:
        upper = Version(1, 0, 0)
    elif minor != 0:
        upper = Version(major, minor + 1, 0)
    elif patch is None:
        upper = Version(major, 1, 0)
    else:
        upper = Version(major, minor, patch + 1)

    return [('>=', lower), ('<', upper)]


def desugar_tilde(major: Optional[int], minor: Optional[int], patch: Optional[int], prerelease: Optional[Tuple[str, ...]], build: Optional[Tuple[str, ...]]) -> List[Tuple[str, Version]]:
    """Desugar a tilde comparator."""
    if major is None:
        raise RangeError("Tilde requires at least a major component")

    lower = Version(major, minor or 0, patch or 0, prerelease or (), build or ())

    if minor is not None:
        upper = Version(major, minor + 1, 0)
    else:
        upper = Version(major + 1, 0, 0)

    return [('>=', lower), ('<', upper)]


def parse_comparator_set(comparator_set_str: str) -> List[Tuple[str, Version]]:
    """Parse a comparator set (whitespace-separated comparators or hyphen range)."""
    tokens = comparator_set_str.split()

    if not tokens:
        raise RangeError("Empty comparator set")

    if len(tokens) == 3 and tokens[1] == '-':
        a_str, _, b_str = tokens

        a_major, a_minor, a_patch, a_prerelease, a_build = parse_partial_version(a_str)
        b_major, b_minor, b_patch, b_prerelease, b_build = parse_partial_version(b_str)

        if a_major is None or b_major is None:
            raise RangeError("Hyphen range requires major version for both bounds")

        lower = Version(a_major, a_minor or 0, a_patch or 0, a_prerelease or (), a_build or ())

        if b_patch is not None:
            upper_version = Version(b_major, b_minor or 0, b_patch, b_prerelease or (), b_build or ())
            return [('>=', lower), ('<=', upper_version)]
        elif b_minor is not None:
            upper = Version(b_major, b_minor + 1, 0)
            return [('>=', lower), ('<', upper)]
        else:
            upper = Version(b_major + 1, 0, 0)
            return [('>=', lower), ('<', upper)]

    if tokens == ['-']:
        raise RangeError("Bare hyphen is malformed")

    if len(tokens) >= 2 and '-' in tokens:
        raise RangeError("Hyphen range must be exactly three tokens: A - B")

    primitives = []
    for token in tokens:
        if token.startswith('>='):
            op = '>='
            version_str = token[2:]
        elif token.startswith('>'):
            op = '>'
            version_str = token[1:]
        elif token.startswith('<='):
            op = '<='
            version_str = token[2:]
        elif token.startswith('<'):
            op = '<'
            version_str = token[1:]
        elif token.startswith('='):
            op = '='
            version_str = token[1:]
        elif token.startswith('^'):
            op = '^'
            version_str = token[1:]
        elif token.startswith('~'):
            op = '~'
            version_str = token[1:]
        else:
            op = '='
            version_str = token

        if not version_str:
            raise RangeError(f"Empty version in comparator: {token}")

        if op in ('>', '>=', '<', '<='):
            version = Version.parse(version_str)
            primitives.append((op, version))
        elif op == '=':
            major, minor, patch, prerelease, build = parse_partial_version(version_str)

            if major is not None and minor is not None and patch is not None:
                version = Version(major, minor, patch, prerelease or (), build or ())
                primitives.append(('=', version))
            else:
                desugared = desugar_bare(major, minor, patch)
                primitives.extend(desugared)
        elif op == '^':
            major, minor, patch, prerelease, build = parse_partial_version(version_str)
            desugared = desugar_caret(major, minor, patch, prerelease, build)
            primitives.extend(desugared)
        elif op == '~':
            major, minor, patch, prerelease, build = parse_partial_version(version_str)
            desugared = desugar_tilde(major, minor, patch, prerelease, build)
            primitives.extend(desugared)

    return primitives


def parse_range_expr(range_expr: str) -> List[List[Tuple[str, Version]]]:
    """Parse a range expression and return comparator sets."""
    if not range_expr.strip():
        return [[('>=', Version(0, 0, 0))]]

    comparator_sets_str = range_expr.split('||')

    comparator_sets = []
    for set_str in comparator_sets_str:
        set_str = set_str.strip()
        if not set_str:
            raise RangeError("Empty comparator set in union")

        primitives = parse_comparator_set(set_str)
        comparator_sets.append(primitives)

    return comparator_sets


def version_satisfies_primitive(version: Version, op: str, comparator_version: Version) -> bool:
    """Check if a version satisfies a primitive comparator."""
    if op == '=':
        return version == comparator_version
    elif op == '>':
        return version.compare(comparator_version) > 0
    elif op == '>=':
        return version.compare(comparator_version) >= 0
    elif op == '<':
        return version.compare(comparator_version) < 0
    elif op == '<=':
        return version.compare(comparator_version) <= 0
    else:
        raise ValueError(f"Unknown operator: {op}")


def version_satisfies_comparator_set(version: Version, comparator_set: List[Tuple[str, Version]]) -> bool:
    """Check if a version satisfies all primitives in a comparator set."""
    for op, comparator_version in comparator_set:
        if not version_satisfies_primitive(version, op, comparator_version):
            return False
    return True


def version_satisfies_with_prerelease_rule(version: Version, comparator_set: List[Tuple[str, Version]]) -> bool:
    """Check if a version satisfies a comparator set, applying the prerelease rule."""
    if not version_satisfies_comparator_set(version, comparator_set):
        return False

    if not version.prerelease:
        return True

    for op, comparator_version in comparator_set:
        if (comparator_version.prerelease and
            comparator_version.major == version.major and
            comparator_version.minor == version.minor and
            comparator_version.patch == version.patch):
            return True

    return False


def max_satisfying(versions: list[str], range_expr: str) -> str | None:
    """Return the highest version in `versions` that satisfies `range_expr`."""
    parsed_versions = []
    for v_str in versions:
        try:
            parsed = Version.parse(v_str)
            parsed_versions.append((v_str, parsed))
        except RangeError:
            raise

    if not versions:
        return None

    try:
        comparator_sets = parse_range_expr(range_expr)
    except RangeError:
        raise

    satisfying = []
    for v_str, parsed_version in parsed_versions:
        for comp_set in comparator_sets:
            if version_satisfies_with_prerelease_rule(parsed_version, comp_set):
                satisfying.append((v_str, parsed_version))
                break

    if not satisfying:
        return None

    max_version_str = satisfying[0][0]
    max_version = satisfying[0][1]

    for v_str, parsed_version in satisfying[1:]:
        if parsed_version.compare(max_version) > 0:
            max_version = parsed_version
            max_version_str = v_str

    return max_version_str
